def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v1 == 0:
        return None

    increase = v2 - v1
    change_ratio = increase / v1
    value = change_ratio * 100

    return {
        "value": value,
        "trace": {
            "starting_value": v1,
            "ending_value": v2,
            "increase": increase,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
